'use strict';
function cloudStatusHTML(){return '<section class="cloud-status-panel"><span id="cloud-status" role="status">'+esc(G11Sync.statusText())+'</span><button id="sync-retry" class="btn secondary">'+t('Coba lagi','Retry')+'</button>'+(G11Sync.backup()?'<button id="cloud-backup" class="btn secondary">'+t('Unduh cadangan lokal','Download local backup')+'</button>':'')+'</section>';}
function feedbackHTML(kind,id){if(typeof G11Sync==='undefined')return '';const r=G11Sync.review(kind,id);if(!r)return '';return '<div class="teacher-feedback"><b>'+t('Feedback guru','Teacher feedback')+' · '+(r.current?(r.status==='accepted'?t('Diterima','Accepted'):r.status==='needs_revision'?t('Perlu revisi','Revise'):t('Sudah dilihat','Seen')):t('Ada versi baru · menunggu pemeriksaan','New version · awaiting review'))+'</b><p>'+esc(r.message||'')+'</p></div>';}

const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let language=new URLSearchParams(location.search).get('lang');
if(!['id','en'].includes(language)){try{language=localStorage.getItem('cs-report-grade11-language')||'en';}catch{language='en';}}
if(!['id','en'].includes(language))language='en';
const t=(id,en)=>language==='id'?id:en;
const tx=pair=>Array.isArray(pair)?pair[language==='id'?0:1]:pair;
let storageKey=null,practice={lessons:{},projects:{},target:{}},storageAvailable=true,currentLesson=null,toastTimer;
function teacherMode(){return g11TeacherVerified===true&&g11Session?.isTeacherPreview===true;}
function lessonRecord(id){if(!practice.lessons[id])practice.lessons[id]={done:false,evidence:'',reflection:'',quiz:{draft:[],best:null,last:null}};return practice.lessons[id];}
function restorePractice(){storageKey='cs-report-grade11-ai-v1:'+encodeURIComponent(g11Session.id);try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw?.lessons&&typeof raw.lessons==='object')for(const l of LESSONS){const r=raw.lessons[l.id];if(r&&typeof r==='object'){const q=r.quiz||{};practice.lessons[l.id]={done:r.done===true,evidence:typeof r.evidence==='string'?r.evidence:'',reflection:typeof r.reflection==='string'?r.reflection:'',quiz:{draft:Array.isArray(q.draft)?q.draft.map(v=>Number.isInteger(v)&&v>=0&&v<3?v:null):[],best:Number.isFinite(q.best)?Math.max(0,Math.min(100,q.best)):null,last:Number.isFinite(q.last)?Math.max(0,Math.min(100,q.last)):null}};}}practice.projects={};for(const s of BSD_SOURCES){const r=raw?.projects?.[s.name];if(r&&typeof r==='object')practice.projects[s.name]={ready:r.ready===true,evidence:typeof r.evidence==='string'?r.evidence:''};}practice.target=raw?.target&&typeof raw.target==='object'?{date:String(raw.target.date||''),unitId:UNITS.some(u=>u.id===raw.target.unitId)?raw.target.unitId:'live',goal:typeof raw.target.goal==='string'?raw.target.goal:''}:{};}catch{storageAvailable=false;practice.projects={};practice.target={};}}

function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(practice));if(typeof G11Sync!=="undefined")G11Sync.enqueue(practice);return true;}catch{storageAvailable=false;toast(t('Belum tersimpan. Unduh catatan sebelum menutup halaman.','Could not save. Download your notes before closing.'));return false;}}
function sourceByName(name){return BSD_SOURCES.find(s=>s.name===name);}
function localizeShell(){document.documentElement.lang=language;$('language').value=language;const labels={'gate-title':t('Buka formatif dari CS.Report.','Open formative tasks from CS.Report.'),'gate-copy':t('Cari nama atau NIS di CS.Report, masukkan password siswa, lalu pilih Buka Formatif.','Search for your name or student ID in CS.Report, enter your student password, then choose Open Formative Tasks.'),'gate-link':t('Cari nama di CS.Report →','Find your name in CS.Report →'),'skip':t('Langsung ke materi','Skip to content'),'nav-home':t('Formatif','Formative tasks'),'nav-project':t('Penilaian','Assessments'),'nav-teacher':t('Panduan guru','Teacher guide'),'book-link':t('Buku nilai ↗','Gradebook ↗'),'footer-copy':t('F1 · Classifier   F2 · KNN   F3 · Navigasi','F1 · Classifier   F2 · KNN   F3 · Navigation'),'cloud-logout':t('Keluar','Sign out'),'storage-copy':t('Kirim bukti, terima feedback, lalu revisi.','Submit evidence, receive feedback, then revise.')};for(const[id,text]of Object.entries(labels))$(id).textContent=text;}



