function lessonHTML(l){const r=lessonRecord(l.id),primary=sourceByName(l.sources[0]);return '<div class="breadcrumbs"><a href="#home">'+t('Course saya','My courses')+'</a> / '+l.id+'</div><header class="lesson-heading"><p class="eyebrow">'+(l.kind?esc(l.kind)+' · ':'')+t('PANDUAN · SESUAI KESIAPAN','GUIDE · WHEN READY')+'</p><h1>'+esc(tx(l.title))+'</h1><p>'+esc(tx(l.goal))+'</p></header><div class="classroom"><section class="panel task-card"><p class="eyebrow">01 · '+t('KERJAKAN','GET STARTED')+'</p><h2>'+t('Kerjakan saat siap','Work on this when ready')+'</h2><p class="bsd-route"><b>BSD:</b> '+l.sources.map(n=>esc(sourceByName(n).title)).join(' · ')+'<br>'+esc(l.range)+'</p>'+(l.starter?'<p class="starter">'+esc(tx(l.starter))+'</p>':'')+'<ol class="task-steps">'+l.tasks.map(s=>'<li>'+esc(tx(s))+'</li>').join('')+'</ol><a class="btn" href="'+esc(primary.url)+'" target="_blank" rel="noopener noreferrer">'+t('Buka proyek BSD ↗','Open BSD project ↗')+'</a></section><section class="panel challenge-card"><p class="eyebrow">02 · '+t('COBA SENDIRI','TRY IT YOURSELF')+'</p><h2>'+t('Tantangan','Challenge')+'</h2><p>'+esc(tx(l.challenge))+'</p><p class="small">'+esc(tx(l.check))+'</p><div class="result-target"><b>'+t('Tunjukkan hasil: ','Show your result: ')+'</b>'+esc(tx(l.result))+'</div></section><section class="panel result-card"><h2>'+t('Simpan hasilmu','Save your result')+'</h2>'+feedbackHTML('lessons',l.id)+'<label for="evidence">'+t('Tautan karya · perubahan & prediksimu','Project link · your change & prediction')+'</label><textarea rows="2" id="evidence" placeholder="'+t('Tautan + saya mengubah… saya memprediksi…','Link + I changed… I predict…')+'">'+esc(r.evidence)+'</textarea><label for="reflection">'+t('Hasil uji & satu keterbatasan','Test results & one limitation')+'</label><textarea rows="2" id="reflection" placeholder="'+t('Input uji → hasil aktual. Batas yang masih ada…','Test input → actual result. Remaining limit…')+'">'+esc(r.reflection)+'</textarea><p class="small">'+(storageAvailable?t('Draft tersimpan saat mengetik. Klik Kirim formatif untuk meminta pemeriksaan.','Your draft saves as you type. Click Submit formative to request review.'):t('Unduh catatan untuk menyimpan hasil.','Download your notes to keep your work.'))+'</p><div class="actions"><button id="complete" class="btn '+(r.done?'done':'')+'">'+(r.done?t('✓ Bukti ditandai siap','✓ Evidence marked ready'):t('Tandai bukti siap','Mark evidence ready'))+'</button><button id="download-note" class="btn secondary">'+t('Unduh catatan','Download notes')+'</button></div></section><details class="panel optional"><summary>'+t('Ringkasan & kuis latihan (pilihan)','Summary & practice quiz (optional)')+'</summary><div><p class="concept-summary">'+esc(tx(l.learn))+'</p><p class="small">'+t('2 soal pendamping · dapat diulang · bukan nilai resmi BSD.','2 companion questions · retry any time · separate from official BSD grades.')+'</p><div id="practice-quiz">'+quizHTML(l)+'</div></div></details>'+(teacherMode()?'<details class="panel teacher-details"><summary>'+t('Pengantar & catatan guru','Teacher introduction & notes')+'</summary>'+teacherLessonHTML(l)+'</details>':'')+'<div class="actions lesson-next">'+(l.id>1?'<a class="btn secondary" href="#lesson/'+(l.id-1)+'">← '+t('Sebelumnya','Previous')+'</a>':'')+(l.id<LESSONS.length?'<a class="btn secondary" href="#lesson/'+(l.id+1)+'">'+t('Panduan berikutnya','Next guide')+' →</a>':'<a class="btn secondary" href="#project">'+t('Demo final →','Final demo →')+'</a>')+'</div></div>';}
function quizHTML(l){const q=lessonRecord(l.id).quiz,finished=q.last!==null;return (finished?'<div class="quiz-result" role="status"><b>'+q.last+'/100</b> · '+t('terbaik: ','best: ')+q.best+'/100</div>':'')+'<form id="quiz-form" class="quiz">'+l.questions.map((question,i)=>'<fieldset><legend>'+(i+1)+'. '+esc(tx(question.stem))+'</legend>'+question.options.map((option,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'" '+(q.draft[i]===j?'checked':'')+' '+(finished?'disabled':'')+' required><span>'+esc(tx(option))+'</span></label>').join('')+(finished?'<p class="explanation">'+(q.draft[i]===question.key?'✓ ':'↗ ')+t('Jawaban: ','Answer: ')+esc(tx(question.options[question.key]))+'. '+esc(tx(question.why))+'</p>':'')+'</fieldset>').join('')+'<button class="btn" type="submit" '+(finished?'disabled':'')+'>'+t('Periksa jawaban','Check answers')+'</button></form>'+(finished?'<button class="btn secondary" id="retry" style="margin-top:12px">'+t('Ulangi latihan','Retry practice')+'</button>':'');}
function recordQuiz(l,answers){if(answers.length!==l.questions.length||answers.some(a=>!Number.isInteger(a)||a<0||a>2))return false;const q=lessonRecord(l.id).quiz,score=Math.round(answers.filter((a,i)=>a===l.questions[i].key).length/answers.length*100);q.draft=answers.slice();q.last=score;q.best=q.best===null?score:Math.max(q.best,score);save();return true;}
function bindQuiz(l){const form=$('quiz-form');form.addEventListener('change',()=>{const q=lessonRecord(l.id).quiz;q.draft=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});save();});form.addEventListener('submit',event=>{event.preventDefault();const answers=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});if(!recordQuiz(l,answers))return;$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});if($('retry'))$('retry').addEventListener('click',()=>{const q=lessonRecord(l.id).quiz;q.last=null;q.draft=[];save();$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});}
function bindLesson(){}
function noteText(l){const r=lessonRecord(l.id);return l.id+'. '+tx(l.title)+'\n\n'+t('Hasil: ','Result: ')+r.evidence+'\n'+t('Refleksi: ','Reflection: ')+r.reflection+'\n'+t('Selesai: ','Complete: ')+r.done+'\n'+t('Skor latihan terbaik: ','Best practice score: ')+(r.quiz.best??'—')+'\n\n'+t('Catatan pribadi pada browser ini; bukan nilai resmi.','Personal browser notes; separate from official grades.');}
function download(name,text){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function teacherLessonHTML(l){if(!teacherMode())return '';return '<p><b>'+t('Pengantar lisan: ','Spoken introduction: ')+'</b>'+esc(tx(l.goal))+' '+esc(tx(l.learn))+'</p><p><b>'+t('Hasil yang diharapkan: ','Expected result: ')+'</b>'+esc(tx(l.result))+'</p><p><b>'+t('Saat berkeliling: ','While circulating: ')+'</b>'+esc(tx(l.oral))+'</p><p><b>'+t('Persiapan teknis: ','Technical preparation: ')+'</b>'+esc(tx(l.prep))+'</p><p><b>WKA / BCW: </b>'+esc(tx(l.wka))+'</p>';}

