/* The student website now focuses on the three formative submissions. */
const FORMATIVE_IDS=[1,4,13];
const formativeLessons=()=>FORMATIVE_IDS.map(id=>LESSONS.find(l=>l.id===id));
let formativeRouteHash='';
function formativeStatus(l){const r=lessonRecord(l.id),review=typeof G11Sync!=='undefined'?G11Sync.review('lessons',l.id):null;if(review?.current&&review.status==='needs_revision')return t('Perlu revisi','Revise');if(r.done&&review?.current&&review.status==='accepted')return t('Sudah diperiksa','Reviewed');return r.done?t('Diajukan','Submitted'):r.evidence||r.reflection?t('Draft','Draft'):t('Belum dikirim','Not submitted');}
homeHTML=function(){return '<section class="home-intro"><p class="eyebrow">GRADE 11 · BSD AI</p><h1>'+t('Tugas formatif saya','My formative tasks')+'</h1><p>'+t('Belajar di BSD. Di sini cukup pilih tugas, kirim bukti, lalu lihat feedback guru.','Learn in BSD. Here, choose a task, submit evidence, and check your teacher’s feedback.')+'</p></section><div class="formative-list">'+formativeLessons().map(l=>'<a class="formative-card" href="#lesson/'+l.id+'"><span class="lesson-number">'+l.kind+'</span><div><h2>'+esc(tx(l.title).replace(/^F[123] · /,''))+'</h2><p>'+esc(tx(l.goal))+'</p><span class="submission-status">'+formativeStatus(l)+'</span></div><span aria-hidden="true">→</span></a>').join('')+'</div>';};
bindHome=function(){};
const originalFormativeLessonHTML=lessonHTML;
lessonHTML=function(l){const r=lessonRecord(l.id);return originalFormativeLessonHTML(l).replace(/<div class="actions lesson-next">.*<\/div><\/div>$/,'</div>').replace(t('Course saya','My courses'),t('Semua formatif','All formative tasks')).replace(t('Kerjakan saat siap','Work on this when ready'),t('Kerjakan','Do the task')).replace(t('Simpan hasilmu','Save your result'),t('Kirim ke guru','Submit to your teacher')).replace(t('Tandai bukti siap','Mark evidence ready'),t('Kirim formatif','Submit formative')).replace(t('✓ Bukti ditandai siap','✓ Evidence marked ready'),t('✓ Diajukan','✓ Submitted')).replace(/<button id="complete"/,'<button id="complete" '+(r.done?'disabled':''));};
bindLesson=function(l){for(const key of ['evidence','reflection'])$(key).addEventListener('input',()=>{const r=lessonRecord(l.id);r[key]=$(key).value;r.done=false;$('complete').disabled=false;$('complete').classList.remove('done');$('complete').textContent=t('Kirim formatif','Submit formative');save();});$('complete').addEventListener('click',()=>{const r=lessonRecord(l.id);if(!r.evidence.trim()||!r.reflection.trim()){toast(t('Isi tautan/perubahan dan hasil uji dahulu.','Add your project/change and test results first.'));return;}r.done=true;save();$('complete').disabled=true;$('complete').classList.add('done');$('complete').textContent=t('✓ Diajukan','✓ Submitted');if(typeof G11Sync!=='undefined')G11Sync.flush();});$('download-note').addEventListener('click',()=>download(l.kind+'-evidence.txt',noteText(l)));bindQuiz(l);};
teacherHTML=function(){if(!teacherMode())return homeHTML();return '<section class="home-intro"><p class="eyebrow">'+t('KHUSUS GURU','TEACHER ONLY')+'</p><h1>'+t('Tiga formatif. Bukti yang jelas.','Three formative tasks. Clear evidence.')+'</h1><p>'+t('Lanjutkan course BSD sesuai tempo siswa. Gunakan web untuk bukti, feedback, revisi, dan nilai F1–F3.','Continue BSD at each student’s pace. Use this website for evidence, feedback, revisions, and F1–F3 grades.')+'</p></section><div class="classroom">'+formativeLessons().map(l=>'<section class="panel"><h2>'+esc(tx(l.title))+'</h2><p>'+esc(tx(l.result))+'</p><p><b>'+t('Saat memeriksa: ','While reviewing: ')+'</b>'+esc(tx(l.oral))+'</p><p><b>WKA: </b>'+esc(tx(l.wka))+'</p><a class="btn secondary" href="#lesson/'+l.id+'">'+t('Lihat tugas','View task')+'</a></section>').join('')+'<a class="btn" href="../dashboard.html">'+t('Buka bukti & nilai siswa →','Open student evidence & grades →')+'</a></div>';};
route=function(){const [page,id]=location.hash.replace(/^#/,'').split('/');currentLesson=null;if(page==='teacher'&&!teacherMode()||page==='course'||page==='project'||page==='lesson'&&!FORMATIVE_IDS.includes(Number(id))){location.hash='#home';return route();}if(page==='lesson')currentLesson=LESSONS.find(l=>l.id===Number(id));$('main').innerHTML=(typeof G11Sync!=='undefined'?cloudStatusHTML():'')+(currentLesson?lessonHTML(currentLesson):page==='teacher'?teacherHTML():homeHTML());if(currentLesson)bindLesson(currentLesson);if($('sync-retry'))$('sync-retry').addEventListener('click',()=>G11Sync.flush());if($('cloud-backup'))$('cloud-backup').addEventListener('click',()=>download('ai-local-backup.json',JSON.stringify(G11Sync.backup(),null,2)));document.title=(currentLesson?currentLesson.kind+' · ':'')+'AI Formative · Grade 11';if(formativeRouteHash!==location.hash){formativeRouteHash=location.hash;window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}};

$('language').addEventListener('change',event=>{language=event.target.value;try{localStorage.setItem('cs-report-grade11-language',language);}catch{}const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);localizeShell();if(g11Session){$('learner-class').textContent=teacherMode()?t('Review guru · Kelas 11','Teacher review · Grade 11'):t('Kelas ','Class ')+g11Session.className;route();}});
async function start(){localizeShell();$('cloud-logout').addEventListener('click',async()=>{if(typeof G11Sync!=='undefined')G11Sync.dispose();if(!g11Session.isLocalPreview&&typeof G11CloudIdentity!=='undefined')await G11CloudIdentity.logout();location.href='../index.html';});if(!(await initializeG11Access()))return;restorePractice();if(typeof G11Sync!=='undefined'){const merge=next=>{practice.lessons={...practice.lessons,...next.lessons};practice.projects={...practice.projects,...next.projects};practice.target=next.target||practice.target;try{localStorage.setItem(storageKey,JSON.stringify(practice));}catch{}if($('main').innerHTML&&!['TEXTAREA','INPUT','SELECT'].includes(document.activeElement?.tagName))route();};const synced=await G11Sync.init(practice,merge);merge(synced);G11Sync.subscribe(()=>{if($('cloud-status'))$('cloud-status').textContent=G11Sync.statusText();if($('main').innerHTML&&!['TEXTAREA','INPUT','SELECT'].includes(document.activeElement?.tagName))route();});}$('nav-teacher').hidden=!teacherMode();$('review-banner').hidden=!(teacherMode()||g11Session.isLocalPreview);$('review-banner').textContent=teacherMode()?t('Review guru. Catatan ini terpisah dari siswa.','Teacher review. These records are separate from students.'):t('Pratinjau lokal dengan siswa uji. Tanpa data siswa nyata.','Local preview with a test student. No real student data.');window.addEventListener('hashchange',route);route();}
start().catch(error=>{$('learning-app').hidden=true;$('access-gate').hidden=false;$('gate-copy').textContent=error.message||t('Materi belum termuat. Buka ulang dari CS.Report.','Materials could not load. Reopen from CS.Report.');});
